// a default method in the Java ToyFlow interface
default ToyFlow<T> timeDownstream(BiConsumer<T, Long> record) {
    return downstream -> this.collect(value -> {
        long start = System.nanoTime();                                 // 1. start the clock
        downstream.emit(value);                                         // 2. everything below runs here
        record.accept(value, (System.nanoTime() - start) / 1_000_000);  // 3. stop it, in ms
    });
}

